          await addStatusReaction(env, job, dependencies);
          message.ack();
        } catch (error) {
          const fields = {
            attempts: message.attempts,
            deliveryId: job.deliveryId.slice(0, 128),
            error: error instanceof Error ? error.name : typeof error,
            ...errorLogFields(error),
            messageId: message.id,
            queue: batch.queue,
