      issuerToken: { token: "" },
      onBrokerCall() {
        brokerCalls += 1;
      },
    });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope })).rejects.toThrow(
      "IssuedToken.token must be a non-empty string",
