name: ci

on:
  pull_request:
  push:
    branches:
      - main

permissions:
  contents: read

concurrency:
  group: ${{ github.workflow }}-${{ github.event.pull_request.number || github.run_id }}
  cancel-in-progress: true

jobs:
  format:
    uses: ./.github/workflows/ci-format.yml

  lint:
    uses: ./.github/workflows/ci-lint.yml

  env-types:
    uses: ./.github/workflows/ci-env-types.yml

  typecheck:
    uses: ./.github/workflows/ci-typecheck.yml

  knip:
    uses: ./.github/workflows/ci-knip.yml

  test:
    permissions:
      contents: read
      id-token: write
    uses: ./.github/workflows/ci-test.yml

  deploy-dry-run:
    uses: ./.github/workflows/ci-deploy-dry-run.yml

  ci:
    name: ci
    runs-on: ubuntu-latest
    needs:
      - format
      - lint
      - env-types
      - typecheck
      - knip
      - test
      - deploy-dry-run
    if: ${{ always() }}
    steps:
      - name: Require all CI jobs to pass
        run: |
          if [[ "${{ contains(needs.*.result, 'failure') }}" == "true" ]]; then
            exit 1
          fi

          if [[ "${{ contains(needs.*.result, 'cancelled') }}" == "true" ]]; then
            exit 1
          fi

          if [[ "${{ contains(needs.*.result, 'skipped') }}" == "true" ]]; then
            exit 1
          fi
